head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf90000";

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf90000.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $c.util.getComponent("ipt_road").focus();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_type1_onclick
 * @description 「1」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_type1_onclick = function(e){
    try {
        scwin.chgSearchType('__self.value')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90000.ipt_type1_onclick' }); }
};

/**
 * @method
 * @name ipt_type2_onclick
 * @description 「2」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_type2_onclick = function(e){
    try {
        scwin.chgSearchType('__self.value')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90000.ipt_type2_onclick' }); }
};

/**
 * @method
 * @name ipt_road_onkeyup
 * @description ipt_road 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_road_onkeyup = async function(e){
    try {
        const ev = e;
        const event = ev;
        scwin.delSpace();if(event.keyCode===13){ await scwin.search();}

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90000.ipt_road_onkeyup' }); }
};

/**
 * @method
 * @name ipt_building_onkeyup
 * @description ipt_building 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_building_onkeyup = async function(e){
    try {
        const ev = e;
        const event = ev;
        scwin.delSpace();if(event.keyCode===13){ await scwin.search();}

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90000.ipt_building_onkeyup' }); }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description btn_Search 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90000.btn_Search_onclick' }); }
};

/**
 * @method
 * @name ipt_road1_onkeyup
 * @description ipt_road1 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_road1_onkeyup = async function(e){
    try {
        const ev = e;
        const event = ev;
        scwin.delSpace();if(event.keyCode===13){ await scwin.search();}

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90000.ipt_road1_onkeyup' }); }
};

/**
 * @method
 * @name btn_Search_2_onclick
 * @description btn_Search_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_2_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90000.btn_Search_2_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description btn_window 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf90000.btn_window_onclick' }); }
};

/**
 * @method
 * @name __on_enter_7_ipt_building1
 * @description on enter 7 ipt building1 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_7_ipt_building1 = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.search() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf90000.__on_enter_7_ipt_building1' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/common/zipList.do?method=zipList",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    if (!await scwin.checkValues()) {
        return;
    }
    (document.JLDINF90000 || { elements: [] }).target = 'iframe';
    (document.JLDINF90000 || { elements: [] }).action = '/common/zipList.do?method=zipList';
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name delSpace
 * @description del Space 처리
 * @returns {void}
 * @hidden N
 */
scwin.delSpace = function () {
    $c.util.getComponent("ipt_road").setValue($c.str.replaceAll($c.util.getComponent('ipt_road').getValue(), " ", ""));
    $c.util.getComponent("ipt_road1").setValue($c.str.replaceAll($c.util.getComponent('ipt_road1').getValue(), " ", ""));
};

/**
 * @method
 * @name checkValues
 * @description check Values 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkValues = async function () {
    if ($c.util.getComponent('ipt_road').getValue().indexOf('%') !== -1 || $c.util.getComponent('ipt_road1').getValue().indexOf('%') !== -1 || $c.util.getComponent('ipt_building').getValue().indexOf('%') !== -1 || $c.util.getComponent('ipt_building1').getValue().indexOf('%') !== -1) {
        await $c.win.alert("'%' 문자는 입력할 수 없습니다.");
        return false;
    }
    if (((!$c.util.getComponent('ipt_type2') || typeof $c.util.getComponent('ipt_type2').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_type2'), false) : ($c.util.getComponent('ipt_type2').getValue() != null && String($c.util.getComponent('ipt_type2').getValue()) !== '')) === true) {
        $c.util.getComponent('ipt_searchWord').setValue(($c.util.getComponent("ipt_road1").getValue() || ''));
        const building1 = $c.util.getComponent('ipt_building1').getValue().trim();
        if (building1.length < 2) {
            if (building1.length > 0) {
                await $c.win.alert('건물명은 최소 2글자 이상 입력하세요.');
                $c.util.getComponent('ipt_building1').setValue(building1);
                ($c.util.getComponent('ipt_building1') && $c.util.getComponent('ipt_building1').setFocus ? $c.util.getComponent('ipt_building1').setFocus() : ($c.util.getComponent('ipt_building1') && $c.util.getComponent('ipt_building1').focus ? $c.util.getComponent('ipt_building1').focus() : console.warn('[sdd] focus 대상 미해결: ipt_building1')));
                return false;
            } else {
                await $c.win.alert('건물명은 최소 2글자 이상 입력하세요.');
                ($c.util.getComponent('ipt_building1') && $c.util.getComponent('ipt_building1').setFocus ? $c.util.getComponent('ipt_building1').setFocus() : ($c.util.getComponent('ipt_building1') && $c.util.getComponent('ipt_building1').focus ? $c.util.getComponent('ipt_building1').focus() : console.warn('[sdd] focus 대상 미해결: ipt_building1')));
                return false;
            }
        } else {
            return true;
        }
    } else {
        if (((!$c.util.getComponent('ipt_type1') || typeof $c.util.getComponent('ipt_type1').getValue !== 'function') ? (console.warn('[sdd] .checked 대상 미해결: ipt_type1'), false) : ($c.util.getComponent('ipt_type1').getValue() != null && String($c.util.getComponent('ipt_type1').getValue()) !== '')) === true) {
            $c.util.getComponent('ipt_searchWord').setValue(($c.util.getComponent("ipt_road").getValue() || ''));
            const roadNm = $c.util.getComponent('ipt_searchWord').getValue().trim();
            if (roadNm.length < 2) {
                await $c.win.alert('도로명은 최소 2글자 이상 입력하세요.');
                $c.util.getComponent("ipt_road").focus();
                return false;
            } else {
                return true;
            }
        } else {
            await $c.win.alert('검색조건을 선택하세요.');
            return false;
        }
    }
};

/**
 * @method
 * @name chgSearchType
 * @description chg Search Type 처리
 * @param {*} searchType searchType
 * @returns {void}
 * @hidden N
 */
scwin.chgSearchType = function (searchType) {
    const divType1 = $c.util.getComponent('searchType1');
    const divType2 = $c.util.getComponent('searchType2');
    const notiType1 = $c.util.getComponent('noticeType1');
    const notiType2 = $c.util.getComponent('noticeType2');
    if (searchType === '1') {
        $c.util.getComponent("ipt_road").setValue("");
        building1.setValue("");
        (!divType1 ? console.warn('[sdd] 표시 전환 대상 미해결: divType1') : (("") === 'none' ? (divType1.hide ? divType1.hide() : void 0) : (divType1.show ? divType1.show() : void 0)));
        (!divType2 ? console.warn('[sdd] 표시 전환 대상 미해결: divType2') : (("none") === 'none' ? (divType2.hide ? divType2.hide() : void 0) : (divType2.show ? divType2.show() : void 0)));
        (!notiType1 ? console.warn('[sdd] 표시 전환 대상 미해결: notiType1') : (("") === 'none' ? (notiType1.hide ? notiType1.hide() : void 0) : (notiType1.show ? notiType1.show() : void 0)));
        (!notiType2 ? console.warn('[sdd] 표시 전환 대상 미해결: notiType2') : (("none") === 'none' ? (notiType2.hide ? notiType2.hide() : void 0) : (notiType2.show ? notiType2.show() : void 0)));
    } else {
        if (searchType === '2') {
            $c.util.getComponent("ipt_road1").setValue("");
            $c.util.getComponent("ipt_building").setValue("");
            (!divType1 ? console.warn('[sdd] 표시 전환 대상 미해결: divType1') : (("none") === 'none' ? (divType1.hide ? divType1.hide() : void 0) : (divType1.show ? divType1.show() : void 0)));
            (!divType2 ? console.warn('[sdd] 표시 전환 대상 미해결: divType2') : (("") === 'none' ? (divType2.hide ? divType2.hide() : void 0) : (divType2.show ? divType2.show() : void 0)));
            (!notiType1 ? console.warn('[sdd] 표시 전환 대상 미해결: notiType1') : (("none") === 'none' ? (notiType1.hide ? notiType1.hide() : void 0) : (notiType1.show ? notiType1.show() : void 0)));
            (!notiType2 ? console.warn('[sdd] 표시 전환 대상 미해결: notiType2') : (("") === 'none' ? (notiType2.hide ? notiType2.hide() : void 0) : (notiType2.show ? notiType2.show() : void 0)));
        }
    }
};

/**
 * @method
 * @name setZipCode
 * @description set Zip Code 처리
 * @param {*} zipcd zipcd
 * @param {*} addr addr
 * @param {*} eng_addr eng_addr
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setZipCode = async function (zipcd, addr, eng_addr) {
    try {
        ((scwin.opener().getComponentById('zipcd_seq')) && (scwin.opener().getComponentById('zipcd_seq')).setValue ? (scwin.opener().getComponentById('zipcd_seq')).setValue(1) : void (1));
        ((scwin.opener().getComponentById('zipcd')) && (scwin.opener().getComponentById('zipcd')).setValue ? (scwin.opener().getComponentById('zipcd')).setValue(zipcd) : void (zipcd));
        ((scwin.opener().getComponentById('addr')) && (scwin.opener().getComponentById('addr')).setValue ? (scwin.opener().getComponentById('addr')).setValue(addr) : void (addr));
        ((scwin.opener().getComponentById('dtl_addr')) && (scwin.opener().getComponentById('dtl_addr')).setValue ? (scwin.opener().getComponentById('dtl_addr')).setValue("") : void (""));
        ((scwin.opener().getComponentById('eng_addr')) && (scwin.opener().getComponentById('eng_addr')).setValue ? (scwin.opener().getComponentById('eng_addr')).setValue(eng_addr) : void (eng_addr));
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldinf90000' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n");
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};
